import { edit_tv_board_details } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    tvboardDeletion: Boolean,
    detailstvboard: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_tv_board_details, {
          input: {
            action_type: "DELETE",
            tv_board_id: this.detailstvboard.tv_board_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_tv_board_details);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
